// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2020, "4-5", [{"author":"И. Иткин","question":"Согласно одной шутке, собака по кличке ... может произнести почти половину своего имени.","choices":["<em>Шарик</em>","<em>Бобик</em>","<em>Гаврила</em>","<em>Капитан</em>","<em>Вальдемар</em>."],"key":"В","review":["Собачья кличка","Вспомни, как записывают лай собаки. Среди вариантов ищи кличку, которая начинается с «гав».","Кличка «Гаврила» начинается с «гав», это три буквы из семи. По шутке собака произносит почти половину имени. Ответ В."]},{"author":"Е. Муравенко","question":"<em>Граф</em>, <em>графа</em>, <em>графин</em>, <em>графиня</em>. Какая пара слов здесь может обозначать мужа и жену?","choices":["<em>граф</em> и <em>графа</em>","<em>граф</em> и <em>графиня</em>","<em>графин</em> и <em>графа</em>","<em>графин</em> и <em>графиня</em>","здесь нет таких слов."],"key":"Б","review":["Муж и жена","Графа — клетка или столбец в таблице, а графин — сосуд для напитков. Мужа и жену нужно искать среди слов с титулами.","«Граф» — титул мужчины, «графиня» — соответствующий титул женщины. Эти слова могут назвать супружескую пару. Ответ Б."]},{"author":"С. Дьяченко","question":"В какой паре отношения между словами совсем не такие, как в остальных?","choices":["<em>решить —</em> <em>решать</em>","<em>вступить</em> <em>— вступать</em>","<em>вручить —</em> <em>вручать</em>","<em>купить —</em> <em>купать</em>","<em>лишить —</em> <em>лишать</em>."],"key":"Г","review":["Два вида глаголов","В парах «решить — решать», «вступить — вступать», «вручить — вручать» и «лишить — лишать» первое слово отвечает на «что сделать?», второе — на «что делать?». Действие сохраняется.","«Купить» значит приобрести, а «купать» — мыть кого-то в воде. Для первого слова парой было бы «покупать». Отличается вариант Г."]},{"author":"М. Мирошниченко","question":"Про мальчика Костю говорят, что он за словом в карман не лезет, на уроках часто бьёт баклуши, никогда не вешает нос, зато часто его задирает. А значит, о Косте нельзя сказать, что он ______.","choices":["жизнерадостный","трудолюбивый","находчивый","хвастливый","остроумный."],"key":"Б","review":["Костя и его привычки","«За словом в карман не лезет» означает, что Костя умеет находчиво ответить. «Не вешает нос» — не унывает, а «задирает нос» — важничает.","«Бить баклуши» значит бездельничать. Частое безделье на уроках в этом описании не согласуется с трудолюбием, вариант Б."]},{"author":"О. Подлесская","question":"Посмотрите на начало известной считалки. В ней из пропущенного слова в каждой следующей строчке убирается по одной букве, начиная с первой.\n\nНа судне ____\nПосле _____\nСлучилась ____,\nПропала _____.\n\nКак называлось судно?","choices":["«Удача»","«Фортуна»","«Победа»","«Русалка»","«Сирена»."],"key":"В","review":["Судно из считалки","Начни с конца. Пропасть могла «еда», случиться могла «беда», а случилась она после «обеда». Каждое следующее слово короче предыдущего на первую букву.","К «обеда» спереди добавь п. Получится «Победа» — название судна, из которого последовательно выходят три остальных слова. Ответ В."]},{"author":"О. Подлесская","question":"<em>Яйцо — скорлупа</em>, <em>банан — кожура</em>, <em>лук —</em> … .","choices":["<em>чешуя</em>","<em>шелуха</em>","<em>кора</em>","<em>кожа</em>","<em>стрела</em>."],"key":"Б","review":["Что покрывает лук","Скорлупа защищает яйцо снаружи, а кожура покрывает банан. По этому же правилу нужно назвать внешнюю оболочку луковицы.","Сухие слои, которые снимают при чистке лука, называют шелухой. Соответствует вариант Б."]},{"author":"И. Рубанов","question":"<em>Я это сделаю в два счёта.</em> Что означает эта фраза?","choices":["я сделаю это очень быстро","я не смогу сделать это быстро","я сделаю это в два этапа","я сделаю это за два дня","мою работу надо будет оплатить по двум отдельным счетам."],"key":"А","review":["Обещание в два счёта","Представь, сколько времени нужно, чтобы произнести «раз, два». Это занимает совсем немного времени.","Фраза «сделаю в два счёта» обещает, что дело будет сделано очень быстро. Это вариант А."]},{"author":"М. Мирошниченко","question":"Какое слово не связано по смыслу с другими?","choices":["<em>звонарь</em>","<em>зазвенеть</em>","<em>звонкий</em>","<em>перезвон</em>","<em>позвонок</em>."],"key":"Д","review":["Пять похожих слов","Звонарь звонит в колокола, зазвенеть — начать звенеть, звонкий описывает звук, а перезвон связан с чередой звонов.","Позвонок — кость, из таких костей состоит позвоночник. Звон в его значении отсутствует, поэтому лишний вариант Д."]},{"author":"Б. Иомдин","question":"Майкл впервые приехал в Россию. Как-то он пошёл гулять во двор, где ребята играли в прятки. Через некоторое время Майкл сказал, что знает русские названия чисел от 1 до 5. Названия какого числа он на самом деле, скорее всего, не узнал?","choices":["1","2","3","4","5."],"key":"А","review":["Счёт во дворе","В прятках часто начинают считалку со слов «раз, два, три, четыре, пять». Майкл, скорее всего, услышал эти слова.","При счёте «раз» обозначает первое число, но его обычное название — «один». Этого слова в считалке он не услышал. Ответ А."]},{"author":"Л. Фёдорова","question":"В каком из глаголов значение приставки отличается от остальных?","choices":["<em>убежать</em>","<em>улететь</em>","<em>ускакать</em>","<em>усидеть</em>","<em>уплыть</em>."],"key":"Г","review":["Куда ведёт приставка у-","Убежать, улететь, ускакать и уплыть обозначают уход из какого-то места. Приставка у- во всех четырёх случаях добавляет значение удаления.","Усидеть — суметь остаться на месте, например на стуле. У приставки здесь другое значение. Подходит вариант Г."]},{"author":"Е. Муравенко","question":"В каком из двустиший, взятых из стихотворений Самуила Маршака, на месте обоих пропусков следует вставить мягкий знак?","choices":["Приходите к Мише в гос_ти,\nСладкий пряник Мише брос_те.","Даже львы меня боят_ся…\nКак над ними не смеят_ся?","Нельзя грубить и чванит_ся.\nЗнакомым надо кланят_ся.","Нет, твой голос нехорош_.\nСлишком тихо ты поёш_!","Медведя лет пяти-шес_ти\nУчили, как себя вес_ти."],"key":"В","review":["Пропуски в стихах Маршака","В выражениях «нельзя чваниться» и «надо кланяться» оба глагола отвечают на вопрос «что делать?». В неопределённой форме перед -ся пишут мягкий знак.","В других парах хотя бы в одном из мест ь не нужен — «гости», «боятся», «нехорош» и «шести». Два мягких знака получаются только в варианте В."]},{"author":"Е. Бикмаев","question":"В одном рассказе упоминается человек, будто бы говоривший плечами. А что он ими «говорит»?","choices":["<em>Спасибо!</em>","<em>Пожалуйста!</em>","<em>Да.</em>","<em>Нет.</em>","<em>Не знаю.</em>"],"key":"Д","review":["Разговор без слов","Представь, что тебя спросили о чём-то, а ответа ты не знаешь. Можно поднять и опустить плечи, то есть пожать ими.","Собеседник поймёт этот жест как «Не знаю». В рассказе человек мог «сказать» плечами именно это, вариант Д."]},{"author":"И. Рубанов","question":"<em>Абонемент на полгода</em> <em>—</em> это <em>... абонемент</em>.","choices":["<em>полугодовалый</em>","<em>полугодовой</em>","<em>полугодный</em>","<em>полгодный</em>","<em>полугодовый</em>."],"key":"Б","review":["Абонемент на полгода","Абонемент на год называется «годовой». Для срока в полгода нужно сохранить это слово и выразить половину года.","Получается «полугодовой абонемент». Слово «полугодовалый» употребляют, когда говорят о возрасте, например о ребёнке. Ответ Б."]},{"author":"Б. Иомдин","question":"<em>Ржится рожь, овёс овсится, ________ _______</em>. Пятое и шестое слова в этом шуточном стихотворении читаются одинаково. Как выглядит пятое слово?","choices":["<em>пшеница</em>","<em>кукуруза</em>","<em>чечевица</em>","<em>фасоль</em>","<em>ячмень</em>."],"key":"В","review":["Два слова с одним звучанием","В каждой паре за названием растения идёт придуманный глагол, например «овёс овсится». Сочетание «-тся» звучит как «-ца».","«Чечеви́ца» и шуточное «чечеви́тся» звучат одинаково. Только чечевица из вариантов заканчивается на «-ца» и даёт такую пару. Ответ В."]},{"author":"Д. Швайгер и Н. Швайгер","question":"Найдите предмет, который не может ни разбиться, ни порваться, ни перегореть, ни сесть.","choices":["лампочка","стул","зеркало","батарейка","рубашка."],"key":"Б","review":["Предмет без пары","Соедини действия с предметами. Лампочка перегорает, зеркало разбивается, рубашка рвётся, а батарейка садится.","На стул можно сесть, а сам он обычно ломается. Ни одно из заданных действий для него не подходит. Стул дан в варианте Б."]},{"author":"П. Аркадьев","question":"Как могут начинаться русские слова?","choices":["<em>жж</em>","<em>зз</em>","<em>чч</em>","<em>шш</em>","<em>щщ</em>."],"key":"А","review":["Две одинаковые согласные","Перебери известные слова с каждым началом. Вспомни, как говорят про жгучую крапиву. Она обжигает, жжётся.","Слова «жжёт» и «жжение» тоже пишутся с начальным жж. Подходит вариант А."]},{"author":"И. Рубанов","question":"Вот четверостишие поэта Эли Бар-Яалома:\nПечник внезапно завопил:\n«Меня природа обманула!\nЯ печки столько лет топил —\nно ни одна не _______!»\n\nКак оканчивается последняя строка?","choices":["<em>полыхнула</em>","<em>громыхнула</em>","<em>утонула</em>","<em>потянула</em>","<em>поблагодарила</em>."],"key":"В","review":["Печник из четверостишия","Глагол «топил» здесь означает, что печник разжигал в печах огонь. Тем же словом можно сказать о том, кто погружает что-то в воду.","Поэт шутит, что при втором значении печки должны были утонуть. «Утонула» ещё и рифмуется с «обманула». Это вариант В."]},{"author":"И. Иткин","question":"Когда-то в одной газете печатались рецензии на телепередачи, подписанные фамилией <em>Кранов</em>, которой предшествовал инициал. Какой?","choices":["<em>Ш</em>","<em>Щ</em>","<em>Э</em>","<em>Ю</em>","<em>Я</em>."],"key":"В","review":["Подпись под телерецензией","Телепередачи смотрят на экране. Если присоединить подходящую букву к началу фамилии «Кранов», получится слово, которое напоминает об экране.","Если прибавить инициал Э, получится «Э. Кранов». Без паузы это звучит как «Экранов» и напоминает о телеэкране. Ответ В."]},{"author":"О. Подлесская","question":"В какой из этих пар оба слова обозначают людей?","choices":["<em>кузнец — кузнечик</em>","<em>рыбак — рыбёшка</em>","<em>портной — портняжка</em>","<em>дворник — дворняжка</em>","<em>сторож — сторожка</em>."],"key":"В","review":["Кого называют в паре","Кузнец, рыбак, портной, дворник и сторож — люди. Проверь вторые слова: кузнечик — насекомое, рыбёшка — рыба, дворняжка — собака, сторожка — помещение.","«Портняжка» — разговорное название портного. Поэтому в этой паре оба слова обозначают людей. Ответ В."]},{"author":"А. Пучкова","question":"Даны числительные на языке бакаири, на котором говорит около 950 человек в Бразилии: 4 — ahage ahage; 5 — ahage ahage tokale; 9 — ahage ahage ahage ahage tokale. Как будет 7 на языке бакаири?","choices":["ahage ahage ahage ahage","ahage ahage tokale tokale tokale","tokale tokale tokale ahage","ahage ahage ahage tokale","tokale ahage ahage ahage."],"key":"Г","review":["Числа на языке бакаири","В записи 4 два одинаковых ahage, значит каждое даёт 2. Чтобы получилось 5, в конец добавили tokale, оно обозначает 1. Запись 9 проверяет правило — четыре двойки и единица в конце.","Для 7 нужны три двойки и единица. Запиши три ahage, затем tokale. Это вариант Г."]},{"author":"Л. Фёдорова","question":"В названии «Сказка о рыбаке и рыбке» 10 согласных звуков. Сколько среди них глухих?","choices":["3","4","5","6","7."],"key":"Д","review":["Звуки в названии сказки","В слове «сказка» слышны [с], [к], [с], [к]. Буква з перед к передаёт глухой [с]. Это четыре глухих согласных.","В «рыбаке» глухой только [к’], а в «рыбке» их два — [п] вместо б перед к и сам [к’]. Складываем 4 + 1 + 2 = 7. Ответ Д."]},{"author":"Б. Иомдин","question":"Взмокший … с поклажей …\nПо дороге вязкой … .\n\nКакого слова нет в этой скороговорке?","choices":["<em>вол</em>","<em>вёл</em>","<em>воз</em>","<em>вёз</em>","все эти слова есть в этой скороговорке."],"key":"Б","review":["Скороговорка с пропусками","«Взмокший» описывает вола, а поклажа лежит на возу. Нужно поставить в первые два пропуска слова «вол» и «воз».","Вол вёз воз по вязкой дороге. Слово «вёз» похоже по звучанию на «воз», поэтому такая фраза подходит для скороговорки. Слово «вёл» в неё не вошло. Это вариант Б."]},{"author":"И. Рубанов","question":"Игорь расставил в записях <em>глотка</em>, <em>звонок</em>, <em>извести</em>, <em>лиса</em>, <em>мало</em>, <em>пробка</em> ударения всеми возможными способами. Сколько различных русских слов у него получилось?","choices":["восемь","девять","десять","одиннадцать","двенадцать."],"key":"Г","review":["Ударения меняют слова","Подбери контекст для каждого ударения. Есть «гло́тка», «ни глотка́», «звоно́к», «голос зво́нок», «и́звести для побелки», «извести́ вредителей», «след ли́са», «рыжая лиса́», «ма́ло воды», «платье мало́».","У слова «про́бка» остаётся один обычный вариант ударения. Пять записей дали по две формы, шестая дала одну. Всего одиннадцать, вариант Г."]},{"author":"Е. Бикмаев","question":"<em>В этом предложении _____ слогов.</em>","choices":["<em>девять</em>","<em>десять</em>","<em>одиннадцать</em>","<em>двенадцать</em>","<em>тринадцать</em>."],"key":"Г","review":["Слоги в предложении","Сосчитай гласные в словах вокруг пропуска. В «этом» два слога, в «предложении» пять, в «слогов» два. «В» слога не добавляет. Итого девять слогов.","«Двенадцать» добавляет три слога, и их действительно становится двенадцать. «Тринадцать» тоже добавляет три, а «одиннадцать» — четыре, поэтому эти числа не сойдутся. «Девять» и «десять» прибавят по два. Ответ Г."]},{"author":"Е. Муравенко","question":"В какой паре у существительных есть совпадающие по звучанию и написанию формы?","choices":["<em>сирень — сирена</em>","<em>пень — пена</em>","<em>лебедь — лебеда</em>","<em>месть — место</em>","<em>тесть — тесто</em>."],"key":"Д","review":["Совпадающие формы слов","Попробуй поставить каждую пару в разные падежи. Например, «о ле́беде» и «о лебеде́» пишутся одинаково, но ударения стоят на разных гласных.","Формы «о те́сте» от «тесть» и «в те́сте» от «тесто» совпадают по буквам и ударению. Подходит пара из варианта Д."]},{"author":"Б. Иомдин","question":"Раньше в Китае использовался особый лунный календарь, а сейчас чаще используется привычный нам европейский. Месяцы какого времени года по европейскому календарю здесь написаны по-китайски?\n\n十二月　 一月　 二月","choices":["зимы","весны","лета","осени","разных."],"key":"А","review":["Месяцы по-китайски","В каждой записи последний знак 月 означает месяц. Первые знаки — его номер. Одна черта 一 означает 1, две черты 二 — 2, а 十 вместе с 二 дают 12.","Получились 12-й, 1-й и 2-й месяцы — декабрь, январь и февраль. Все они относятся к зиме, вариант А."]},{"author":"О. Подлесская","question":"<em>Он полз, пока рука его не … маленького колечка.</em>\nКак правильно заполнить пропуск в соответствии с современной литературной нормой?","choices":["<em>докоснулась</em>","<em>докоснулась до</em>","<em>коснулась до</em>","<em>коснулась</em>","<em>дотронулась</em>."],"key":"Г","review":["Рука и колечко","Сравни два нормативных оборота: «коснуться чего?» и «дотронуться до чего?». В условии после пропуска стоит «маленького колечка» без предлога.","Нужна форма «коснулась» с прямым вопросом «чего?». «Докоснулась» в литературной норме не употребляется. Подходит вариант Г."]},{"author":"А. Панина","question":"У какого из этих слов больше суффиксов, чем у остальных?","choices":["<em>нахальный</em>","<em>подвальный</em>","<em>вокзальный</em>","<em>спальный</em>","<em>пыльный</em>."],"key":"Г","review":["Суффиксы в прилагательных","Сопоставь слова с родственными: нахал — нахальный, подвал — подвальный, вокзал — вокзальный, пыль — пыльный. У всех в этой группе есть по одному суффиксу -н- после основы существительного.","«Спальный» связан с глаголом «спать». Корень сп- виден в «сплю», а после него выделяют глагольный -а- и часть -льн-, которая образует прилагательное. Здесь больше одного суффикса, вариант Г."]},{"author":"И. Рубанов","question":"Игорь придумал новый способ шифровки русских слов. Если он зашифрует слово <em>мир</em>, у него получится <em>нёс</em>, а из слова <em>дар</em> получится <em>жяс</em>. А что у него получится из слова <em>гул</em>?","choices":["<em>дол</em>","<em>дым</em>","<em>вык</em>","<em>дом</em>","<em>вом</em>."],"key":"Г","review":["Игорь шифрует слова","Рассмотри согласные отдельно от гласных. Согласные заменяются следующими согласными по алфавиту: м → н, д → ж, р → с. Гласные заменяются предыдущими в своём ряду: и → ё, а → я с переходом в конец.","Примени правило к слову «гул». У согласных г → д и л → м, а у гласных у → о. Получается «дом», вариант Г."]},{"author":"Л. Фёдорова","question":"Что означает старинное слово <em>лукно</em>?","choices":["‘грядка с луком’","‘берег у излучины реки’","‘часть лука, к которой крепится тетива’","‘корзина’","‘щепка’."],"key":"Г","review":["Что такое лукно","Сравни старинное «лукно» со знакомым словом «лукошко». Оно подсказывает, какой предмет искать среди вариантов.","Даль приводит для слова «лукно» значение плетёной корзинки. Выбираем «корзина», вариант Г."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
